function walletRefund(code){const o=smsOfferFor(code);if(!o||!dreamnet.purchases[o.code]||dreamnet.subscriptions[o.code]?.active)return false;const row=[...dreamnet.ledger].reverse().find(r=>r.title===o.title+' · 单次下载');if(!row)return false;const amount=-row.amount;dreamnet.balance=Math.min(1000000,dreamnet.balance+amount);delete dreamnet.purchases[o.code];walletLedger(o.title+' · 退货退款',amount);phoneState.sent.forEach(r=>{if(smsOfferFor(r.text)?.code===o.code)r.claimed=false;});if(o.wallpaper===phoneState.wallpaperImage)phoneState.wallpaperImage='';savePhone();walletNotice(`【退款成功】${o.title}退回${walletMoney(amount)}元游戏币。下载领取凭证已撤销，已保存到本机的文件不会被删除。`);discover('refund');return true;}
