function resetArcade(id){arcadeGame=id;arcadeMoves=0;if(id==='lights'){lights=Array(9).fill(false);const cells=Array.from({length:9},(_,i)=>i).sort(()=>Math.random()-.5).slice(0,3+Math.floor(Math.random()*4));cells.forEach(toggleLight);if(lights.every(v=>!v))toggleLight(4);}if(id==='memory'){memoryCards=[...'★♪☀♠♥☂★♪☀♠♥☂'].sort(()=>Math.random()-.5);memoryOpen=[];memoryMatched=[];}if(id==='slide'){slideTiles=[1,2,3,4,5,6,7,8,0];let previous=-1;for(let n=0;n<45;n++){const zero=slideTiles.indexOf(0),choices=slideTiles.map((_,i)=>i).filter(i=>i!==previous&&Math.abs(Math.floor(i/3)-Math.floor(zero/3))+Math.abs(i%3-zero%3)===1),next=choices[Math.floor(Math.random()*choices.length)];[slideTiles[zero],slideTiles[next]]=[slideTiles[next],slideTiles[zero]];previous=zero;}}}
function toggleLight(i){const r=Math.floor(i/3),c=i%3;lights=lights.map((v,j)=>Math.abs(Math.floor(j/3)-r)+Math.abs(j%3-c)<=1?!v:v);}
resetArcade('lights');
function arcadePlay(i){if(!Number.isInteger(i))return false;if(arcadeGame==='lights'&&i>=0&&i<9){toggleLight(i);arcadeMoves++;if(lights.every(v=>!v))discover('lights');return true;}if(arcadeGame==='slide'&&i>=0&&i<9){const z=slideTiles.indexOf(0);if(Math.abs(Math.floor(i/3)-Math.floor(z/3))+Math.abs(i%3-z%3)!==1)return false;[slideTiles[i],slideTiles[z]]=[slideTiles[z],slideTiles[i]];arcadeMoves++;if(slideTiles.join(',')==='1,2,3,4,5,6,7,8,0')discover('slide');return true;}if(arcadeGame==='memory'&&i>=0&&i<12&&!memoryMatched.includes(i)&&!memoryOpen.includes(i)){if(memoryOpen.length===2)memoryOpen=[];memoryOpen.push(i);arcadeMoves++;if(memoryOpen.length===2&&memoryCards[memoryOpen[0]]===memoryCards[i]){memoryMatched.push(...memoryOpen);memoryOpen=[];if(memoryMatched.length===12)discover('memory');}return true;}return false;}
function arcadeMarkup(){const won=arcadeGame==='lights'?lights.every(v=>!v):arcadeGame==='memory'?memoryMatched.length===12:slideTiles.join(',')==='1,2,3,4,5,6,7,8,0';return `<section class="pocket-arcade"><header><small>本站原创 / 不限次数</small><h2>课间十分钟</h2></header><nav>${[['lights','九宫熄灯'],['memory','记忆翻牌'],['slide','数字华容道']].map(([id,t])=>`<button data-arcade-select="${id}" aria-pressed="${id===arcadeGame}">${t}</button>`).join('')}</nav><p>${arcadeGame==='lights'?'点格子会反转自己与上下左右，全部熄灭就赢。':arcadeGame==='memory'?'翻出两张相同的贴纸。点第三张后收起上一对。':'点空格旁的数字，把1—8按顺序排好。'}</p><div class="arcade-board ${arcadeGame==='memory'?'board-memory':''}">${(arcadeGame==='lights'?lights:arcadeGame==='memory'?memoryCards:slideTiles).map((v,i)=>`<button data-arcade-cell="${i}" class="${arcadeGame==='lights'&&v?'light-on':''} ${arcadeGame==='memory'&&memoryMatched.includes(i)?'card-matched':''}" aria-label="格子 ${i+1}">${arcadeGame==='lights'?(v?'☀':'·'):arcadeGame==='memory'?(memoryOpen.includes(i)||memoryMatched.includes(i)||discoveries.includes('cheat')?v:'?'):v||''}</button>`).join('')}</div><output>${won?'过关！这段回忆已经收好了。':'已操作 '+arcadeMoves+' 次 · 每次重开都是新题'}</output><button data-arcade-reset>再来一局</button>${discoveries.includes('cheat')&&arcadeGame==='lights'?'<button data-arcade-assist>秘籍：重置为最后一招</button>':''}<p>还有 ${pocketJavaGames.length} 款 Java 小游戏在原来的游戏厅。</p><button data-phone-app="games">打开 Java 游戏厅 ›</button></section>`;}
function supportMarkup(){return `<section class="support-developer"><small>旧日小卖部 / 给开发者</small><h2>喜欢这个小世界？</h2><p>你的掌声，会让这部旧手机再亮久一点。</p><button data-support-applause>♥ 给作者鼓掌 (${supportCount})</button><p>掌声只保存在本机，不消费话费。真正的自愿打赏暂未开放，等待作者配置收款入口。</p><p>想继续加：更多机身机关、联系人支线、原创小游戏和杂志封底。这里会一直保留免费探索。</p></section>`;}
function extraPhoneScreen(app){if(['mp3','mp4'].includes(phoneState.model)){if(app==='music')return offlineMusicMarkup();if(app==='videos')return offlineVideoMarkup();if(app==='photos')return offlinePhotosMarkup();}if(app==='games'&&['iphone','fullscreen','psp','mp5'].includes(phoneState.model))return arcadeMarkup();if(app==='arcade')return arcadeMarkup();if(app==='daming')return damingMarkup();if(app==='support')return supportMarkup();if(app==='home'&&deviceCapabilities[phoneState.model]){const m=phoneModels[phoneState.model];return `<section class="player-home"><small>${m.short} / 随身娱乐</small><h2>${m.name}</h2><p>${m.note}</p>${installedSystemApps().map((a,i)=>`<button class="${i===systemHomeIndex?'system-selected':''}" data-phone-app="${a.id}">${a.icon} ${a.name} ›</button>`).join('')}<small>${['mp3','mp4'].includes(phoneState.model)?'离线设备 · 没有联网和短信':'网页玩具重制 · 功能依设备区分'}</small></section>`;}return null;}
// A real snapshot viewer, kept separate from locally recreated WAP pages.
let phoneArchive={key:'',status:'idle',url:'',timestamp:'',error:''},archiveSerial=0;
const localWebsiteMarkup=phoneWebsiteMarkup;
phoneWebsiteMarkup=function(){if(!deskWebsite)return localWebsiteMarkup();const key=date+'|'+deskWebsite.url;if(phoneArchive.key!==key){phoneArchive={key,status:'loading',url:'',timestamp:'',error:''};queuePhoneArchive(deskWebsite,key);}return `<section class="phone-archive"><header><b>${escapeHTML(deskWebsite.name)}</b><small>真实历史存档 · 目标 ${date}</small></header>${phoneArchive.status==='ready'?`<p>快照：${phoneArchive.timestamp.slice(0,4)}-${phoneArchive.timestamp.slice(4,6)}-${phoneArchive.timestamp.slice(6,8)}</p><iframe title="UC历史网页" src="${escapeHTML(phoneArchive.url)}" sandbox="allow-scripts allow-same-origin" referrerpolicy="no-referrer"></iframe>`:`<p role="status">${phoneArchive.status==='loading'?'正在向 Internet Archive 查找所选年份的快照…':escapeHTML(phoneArchive.error)}</p>`}<div><button data-archive-retry>重新查找</button><a href="https://web.archive.org/web/${date.replaceAll('-','')}000000/${escapeHTML(deskWebsite.url)}" target="_blank" rel="noopener noreferrer">在存档站打开 ›</a></div><p>存档站可能限制嵌入、缺图或暂时不可达；这不会被替换成冒充原站的重制页。</p><details><summary>只看本站重制导航</summary>${localWebsiteMarkup()}</details></section>`;};
async function queuePhoneArchive(site,key){const serial=++archiveSerial,controller=new AbortController(),timer=setTimeout(()=>controller.abort(),8500);try{const endpoint=new URL('https://archive.org/wayback/available');endpoint.searchParams.set('url',site.url);endpoint.searchParams.set('timestamp',date.replaceAll('-','')+'235959');const r=await fetch(endpoint,{signal:controller.signal});if(!r.ok)throw Error('存档服务暂时不可达');const snap=(await r.json()).archived_snapshots?.closest;if(!snap?.available||!/^\d{14}$/.test(snap.timestamp)||!snap.timestamp.startsWith(year())||snap.timestamp>date.replaceAll('-','')+'235959')throw Error('没有找到所选年份内、目标日期以前的快照。可以去存档站手动选日期。');const target=new URL(snap.url);if(target.hostname!=='web.archive.org'||target.username||target.password||!target.pathname.startsWith('/web/'+snap.timestamp+'/'))throw Error('存档地址校验失败');target.protocol='https:';if(serial!==archiveSerial)return;phoneArchive={key,status:'ready',url:target.href,timestamp:snap.timestamp,error:''};}catch(e){if(serial!==archiveSerial)return;phoneArchive={key,status:'error',url:'',timestamp:'',error:e.name==='AbortError'?'存档查询超时，稍后重试或到存档站打开。':e.message};}finally{clearTimeout(timer);if(serial===archiveSerial&&phoneSurfaceActive()&&phoneState.app==='browser'&&ucContent==='web')refreshPhone();}}
let toySound=null,deviceDrag=null;
function keySound(){try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;toySound||=new Audio();toySound.resume();const o=toySound.createOscillator(),g=toySound.createGain();o.type='sine';o.frequency.value=750;g.gain.setValueAtTime(.035,toySound.currentTime);g.gain.exponentialRampToValueAtTime(.001,toySound.currentTime+.06);o.connect(g);g.connect(toySound.destination);o.start();o.stop(toySound.currentTime+.07);}catch{}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-purchase-refund],[data-contact-open],[data-contact-choice],[data-contact-back],[data-daming-page],[data-arcade-select],[data-arcade-cell],[data-arcade-reset],[data-arcade-assist],[data-support-applause],[data-archive-retry]');if(!b)return;e.preventDefault();if(b.dataset.purchaseRefund){if(!walletRefund(b.dataset.purchaseRefund))toast('这项记录无法退款；包月请先退订。');return refreshPhone();}if(b.dataset.contactOpen){contactChat=b.dataset.contactOpen;discover('clue');return refreshPhone();}if(b.hasAttribute('data-contact-back')){contactChat='';return refreshPhone();}if(b.dataset.contactChoice!==undefined){const p=contactPeople.find(p=>p.id===contactChat),answer=p?.choices[Number(b.dataset.contactChoice)]?.[1];if(answer){document.querySelector('[data-contact-reply]').textContent=answer;keySound();}return;}if(b.dataset.damingPage){damingPage=Math.max(0,Math.min(32,damingPage+Number(b.dataset.damingPage)));if(damingPage===32)discover('daming');return refreshPhone();}if(b.dataset.arcadeSelect){if(['lights','memory','slide'].includes(b.dataset.arcadeSelect))resetArcade(b.dataset.arcadeSelect);return refreshPhone();}if(b.dataset.arcadeCell!==undefined){arcadePlay(Number(b.dataset.arcadeCell));keySound();return refreshPhone();}if(b.hasAttribute('data-arcade-reset')){resetArcade(arcadeGame);return refreshPhone();}if(b.hasAttribute('data-arcade-assist')&&discoveries.includes('cheat')){lights=Array(9).fill(false);toggleLight(4);return refreshPhone();}if(b.hasAttribute('data-support-applause')){supportCount++;try{localStorage.setItem('olddays-support-applause',String(supportCount));}catch{}discover('support');return refreshPhone();}if(b.hasAttribute('data-archive-retry')){phoneArchive.key='';return refreshPhone();}});
document.addEventListener('change',e=>{if(e.target.matches('[data-daming-jump]')){damingPage=Math.max(0,Math.min(32,Number(e.target.value)||0));refreshPhone();}});
document.addEventListener('pointerdown',e=>{if(e.target.closest('[data-phone-dir],[data-phone-key],[data-phone-ok],[data-phone-soft]'))keySound();const grip=e.target.closest('[data-device-grip]');if(grip){e.preventDefault();deviceDrag={x:e.clientX,y:e.clientY,grip};try{grip.setPointerCapture(e.pointerId);}catch{}}});
document.addEventListener('pointermove',e=>{if(!deviceDrag)return;const distance=Math.max(-50,Math.min(90,e.clientX-deviceDrag.x)),device=deviceDrag.grip.closest('.museum-device');device?.style.setProperty('--toy-shift',distance+'px');});
document.addEventListener('pointerup',()=>{if(!deviceDrag)return;deviceDrag.grip.closest('.museum-device')?.classList.toggle('toy-open');deviceDrag=null;keySound();discover('twist');});

function offlineMusicMarkup(){return `<section class="player-home"><small>LOCAL MUSIC / 本机曲库</small><h2>掌上随身听</h2><p>仅播放本站合成音乐，不提供上网入口。</p><button data-music-toggle>▶ 播放 / 暂停</button>${memoryTracks.map((t,i)=>`<button data-memory-track="${i}">♪ ${escapeHTML(t.name)}</button>`).join('')}<button data-track-step="-1">上一首</button><button data-track-step="1">下一首</button></section>`;}
function offlineVideoMarkup(){return `<section class="player-home"><small>LOCAL VIDEO / 离线影片</small><h2>窗外的夏天</h2><video controls playsinline preload="metadata" style="width:100%" poster="images/memories/campus.jpg" src="video/pocket-summer.mp4"></video><p>本站原创像素短片 · 本机素材，无外站或联网播放器。</p><a href="video/pocket-summer.mp4" download>保存 MP4 到本机</a></section>`;}
function offlinePhotosMarkup(){return `<section class="player-home"><h2>随身相册</h2>${['campus','night','portrait'].map(k=>`<img src="images/memories/${k}.jpg" alt="本机相片" style="width:100%;margin:8px 0">`).join('')}<p>离线相册，不提供短信或在线下载。</p></section>`;}
const originalGameShelf=phoneGameShelfMarkup;
phoneGameShelfMarkup=function(){return `<button class="phone-native-game" data-phone-app="arcade">✣ 课间小游戏 · 熄灯 / 翻牌 / 华容道 ›</button>`+originalGameShelf();};
let extraHardwareIndex=0;
function extraHardwareAction(b){if(phoneState.app==='daming'){const key=b.dataset.phoneKey,dir=b.dataset.phoneDir;if(key==='4'||dir==='left'||key==='6'||dir==='right'){damingPage=Math.max(0,Math.min(32,damingPage+((key==='4'||dir==='left')?-1:1)));refreshPhone();return true;}return false;}if(!['contacts','arcade'].includes(phoneState.app))return false;const selector=phoneState.app==='contacts'?'.contact-play>button':'[data-arcade-cell]',items=Array.from(document.querySelectorAll(selector));if(!items.length)return false;const dir=b.dataset.phoneDir,key=b.dataset.phoneKey,delta=dir?({up:-3,down:3,left:-1,right:1}[dir]):({2:-3,8:3,4:-1,6:1}[key]);if(delta){extraHardwareIndex=Math.max(0,Math.min(items.length-1,extraHardwareIndex+delta));items.forEach((el,i)=>{el.classList.toggle('hardware-selected',i===extraHardwareIndex);});items[extraHardwareIndex].scrollIntoView?.({block:'nearest'});return true;}if(b.hasAttribute('data-phone-ok')||key==='5'){items[Math.min(extraHardwareIndex,items.length-1)].click();return true;}return false;}
const originalClaim=claimSmsDownload;
claimSmsDownload=function(code){const ok=originalClaim(code),offer=smsOfferFor(code);if(ok&&offer){if(['lights','memory','slide'].includes(offer.play))resetArcade(offer.play);if(offer.play==='cheat')walletNotice('【秘籍小册】向修机师傅打听隐藏口令。');if(offer.play==='overpromise')walletNotice('【下载站回执】海报里的神作其实就是贪吃蛇！找报刊亭老板投诉，可申请20元游戏币退款。');}return ok;};

function renderPlayerWorkbench(){const m=phoneModels[phoneState.model];return `<section class="explore-workbench"><aside class="explore-library"><header class="explore-intro"><small>POCKET PLAYER / ${m.era}</small><h1>${escapeHTML(m.name)}</h1><p>${m.note}。这台设备有自己的玩法和限制。</p></header><section class="exploration-hub"><h2>装进口袋，带去放学路上。</h2><div>${installedSystemApps().map(a=>`<button data-desk-open="${a.id}"><b>${a.icon}</b>${a.name} ›</button>`).join('')}</div><p>${['mp3','mp4'].includes(phoneState.model)?'只有本机素材，没有浏览器、短信、应用商店和话费业务。':'选择游戏或影音，在右侧设备里继续。'}</p></section><button data-phone-picker>再选一部设备 ›</button></aside><section class="home-phone-preview" aria-label="右侧随身设备"><div class="desk-phone-heading"><span>${m.short}</span><button data-phone-picker>换设备</button></div>${renderPhoneLab()}</section></section>`;}

function saveArcade(){try{localStorage.setItem('olddays-arcade-save',JSON.stringify({arcadeGame,lights,memoryCards,memoryOpen,memoryMatched,slideTiles,arcadeMoves}));}catch{}}
try{const p=JSON.parse(localStorage.getItem('olddays-arcade-save')||'null');if(p&&['lights','memory','slide'].includes(p.arcadeGame)&&Array.isArray(p.lights)&&p.lights.length===9&&p.lights.every(v=>typeof v==='boolean')&&Array.isArray(p.slideTiles)&&[...p.slideTiles].sort().join(',')==='0,1,2,3,4,5,6,7,8'){arcadeGame=p.arcadeGame;lights=p.lights;slideTiles=p.slideTiles;arcadeMoves=Number.isInteger(p.arcadeMoves)?Math.max(0,Math.min(99999,p.arcadeMoves)):0;const faces=['★','♪','☀','♠','♥','☂'];if(Array.isArray(p.memoryCards)&&p.memoryCards.length===12&&faces.every(f=>p.memoryCards.filter(v=>v===f).length===2)){memoryCards=p.memoryCards;memoryOpen=Array.isArray(p.memoryOpen)?[...new Set(p.memoryOpen.filter(i=>Number.isInteger(i)&&i>=0&&i<12))].slice(0,2):[];memoryMatched=Array.isArray(p.memoryMatched)?[...new Set(p.memoryMatched.filter(i=>Number.isInteger(i)&&i>=0&&i<12))]:[];}else if(arcadeGame==='memory')resetArcade('memory');}}catch{}
document.addEventListener('click',e=>{if(e.target.closest('[data-arcade-select],[data-arcade-cell],[data-arcade-reset],[data-arcade-assist]'))saveArcade();});
